/**
 * DataList Component
 * 
 * This component displays the list of data records with edit and delete functionality.
 * It handles the display of records and user interactions for CRUD operations.
 * 
 * Props:
 * - records: Array of record objects to display
 * - onEdit: Function to call when edit button is clicked
 * - onDelete: Function to call when delete button is clicked
 * - disabled: Boolean to disable actions during loading
 */

import React from 'react';

const DataList = ({ records, onEdit, onDelete, disabled }) => {
  /**
   * Format date for display
   * @param {string} dateString - ISO date string
   * @returns {string} - Formatted date string
   */
  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  /**
   * Handle edit button click
   * @param {Object} record - The record to edit
   */
  const handleEdit = (record) => {
    onEdit(record);
  };

  /**
   * Handle delete button click
   * @param {string} id - The ID of the record to delete
   */
  const handleDelete = (id) => {
    onDelete(id);
  };

  return (
    <div className="data-list">
      <h2>Records ({records.length})</h2>

      {records.length === 0 ? (
        <div className="empty-state">
          <p>No records found. Add your first record above!</p>
        </div>
      ) : (
        <div className="records-grid">
          {records.map((record) => (
            <div key={record._id} className="record-card">
              <div className="record-header">
                <h3 className="record-title">{record.title}</h3>
                <div className="record-actions">
                  <button
                    onClick={() => handleEdit(record)}
                    disabled={disabled}
                    className="btn btn-edit"
                    title="Edit record"
                  >
                    ✏️
                  </button>
                  <button
                    onClick={() => handleDelete(record._id)}
                    disabled={disabled}
                    className="btn btn-delete"
                    title="Delete record"
                  >
                    🗑️
                  </button>
                </div>
              </div>

              <div className="record-content">
                <p className="record-description">{record.description}</p>
              </div>

              <div className="record-footer">
                <span className="record-date">
                  Created: {formatDate(record.createdAt)}
                </span>
                {record.updatedAt && record.updatedAt !== record.createdAt && (
                  <span className="record-updated">
                    Updated: {formatDate(record.updatedAt)}
                  </span>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default DataList;
